"use client";
import { Mindmap } from "@diax/react";

export default function PlatformMindmap() {
  return (
    <Mindmap
      nodes={[
        { id: "core", content: "Platform" },
        { id: "fe", content: "Frontend" },
        { id: "be", content: "Backend" },
        { id: "infra", content: "Infrastructure" },
        { id: "fe-react", content: "React" },
        { id: "fe-vue", content: "Vue" },
        { id: "be-api", content: "API" },
        { id: "be-db", content: "Database" },
        { id: "infra-ci", content: "CI/CD" },
        { id: "infra-k8s", content: "Kubernetes" },
      ]}
      relations={[
        "core->fe",
        "core->be",
        "core->infra",
        "fe->fe-react",
        "fe->fe-vue",
        "be->be-api",
        "be->be-db",
        "infra->infra-ci",
        "infra->infra-k8s",
      ]}
      density="comfortable"
    />
  );
}
